// Сведения о печати из шапки и хвоста G-code: время, пластик, температуры, сопло, слой,
// принтер, стол, чем и когда нарезано. Каждый слайсер пишет по-своему:
//   PrusaSlicer  «; generated by PrusaSlicer 2.8.1 on 2024-10-21 at 06:38:01 UTC», хвост «; ключ = значение»
//                (между «; prusaslicer_config = begin/end»), стол bed_shape, max_print_height;
//   OrcaSlicer / ElegooSlicer  шапка HEADER_BLOCK, хвост CONFIG_BLOCK, стол printable_area;
//   Bambu Studio «; BambuStudio 01.09.00.70», «; total filament weight [g] : 3.69», «; model printing time: ...; total estimated time: ...»;
//   Cura         «;TIME:», «;Filament used: 1.2m», «;Layer height:», «;TARGET_MACHINE.NAME:», Griffin «;PRINT.TIME:»,
//                настройки в «;SETTING_3 ...» в самом конце;
//   Slicer CC    режет движком Elegoo/Orca, узнаётся по строке «; Slicer CC ...» или имени профиля.
// Чего нет в шапке, то берём из команд (M104/M109, M140/M190) или считаем по длине нити.
'use strict';
const { parseDuration } = require('../shared/gcode-info');

const HEAD = 128 * 1024;
// Метки внутри G-code, а не настройки: в «все настройки файла» не попадают.
const SKIP = new Set(['TYPE', 'Z', 'HEIGHT', 'WIDTH', 'LAYER', 'FEATURE', 'Z_HEIGHT', 'LAYER_HEIGHT', 'TIME_ELAPSED', 'MESH', 'LAYER_CHANGE',
  'layer num/total_layer_count', 'thumbnail begin', 'thumbnail end']);
const TAIL = 512 * 1024;
const DEFAULT_DENSITY = 1.24;
const DEFAULT_DIAMETER = 1.75;

const unquote = (s) => String(s).trim().replace(/^"(.*)"$/, '$1').trim();
const firstOf = (s) => {
  if (s === undefined || s === null) return '';
  const parts = String(s).split(/[;,]/).map(unquote).filter(Boolean);
  return parts[0] || '';
};
const listOf = (s) => (s === undefined || s === null ? [] : String(s).split(/[;,]/).map(unquote).filter(Boolean));
const numOr = (s) => {
  if (s === undefined || s === null || s === '') return null;
  const m = /-?\d+(?:\.\d+)?/.exec(String(s));
  if (!m) return null;
  const n = Number(m[0]);
  return Number.isFinite(n) ? n : null;
};
const sumOf = (s) => {
  const v = String(s === undefined || s === null ? '' : s).split(/[;,]/).map((x) => numOr(x)).filter((x) => x !== null);
  return v.length ? Math.round(v.reduce((a, b) => a + b, 0) * 1000) / 1000 : null;
};

/** Все «; ключ = значение» и «; ключ: значение» из шапки и хвоста. Значение хвоста главнее. */
function collectKeys(text) {
  const kv = {};
  const take = (part) => {
    const re = /^;[ \t]*([A-Za-z_][A-Za-z0-9_ .\[\]^()/-]*?)[ \t]*(=|:)[ \t]*(.*?)\r?$/gm;
    let m;
    while ((m = re.exec(part))) {
      const key = m[1].trim();
      if (!key || key.length > 80 || SKIP.has(key) || key.startsWith('generated by')) continue;
      kv[key] = m[3];
    }
  };
  if (text.length <= HEAD + TAIL) take(text);
  else { take(text.slice(0, HEAD)); take(text.slice(-TAIL)); }
  return kv;
}

/** Cura: ;SETTING_3 {"global_quality": "[general]\\n...\\n[values]\\nlayer_height = 0.2\\n", "extruder_quality": [...]} */
function curaSettings(text) {
  const tail = text.slice(-TAIL);
  const lines = tail.split(/\r?\n/).filter((l) => l.startsWith(';SETTING_3 '));
  if (!lines.length) return {};
  const json = lines.map((l) => l.slice(11)).join('');
  const out = {};
  try {
    const j = JSON.parse(json);
    const blocks = [j.global_quality, ...(Array.isArray(j.extruder_quality) ? j.extruder_quality : [])];
    for (const b of blocks) {
      if (typeof b !== 'string') continue;
      for (const line of b.split('\n')) {
        const m = /^([a-z_0-9]+)\s*=\s*(.*)$/.exec(line.trim());
        if (m && !(m[1] in out)) out[m[1]] = m[2];
      }
    }
  } catch { /* обрезанный хвост - без настроек Cura */ }
  return out;
}

function detectSlicer(text, kv) {
  const head = text.slice(0, 4096);
  let m = /;\s*generated by\s+([A-Za-z][\w .-]*?)\s+v?(\d[\w.+-]*)(?:\s+on\s+(\d{4}-\d{2}-\d{2})\s+at\s+(\d{2}:\d{2}:\d{2})(\s*UTC)?)?/i.exec(head);
  let name = '', version = '', date = null;
  if (m) {
    name = m[1].trim(); version = m[2].replace(/\+.*$/, '');
    if (m[3]) date = m[3] + 'T' + m[4] + (m[5] ? 'Z' : '');
  } else if ((m = /Simplify3D\(R\) Version (\S+)/.exec(head))) {
    name = 'Simplify3D'; version = m[1];
  } else if ((m = /^;\s*(BambuStudio|OrcaSlicer|ElegooSlicer)\s+v?(\d[\w.+-]*)/im.exec(head))) {
    name = m[1]; version = m[2];
  } else if ((m = /^;\s*Generated with Cura_SteamEngine\s+(\S+)/im.exec(text.slice(0, 4096) + '\n' + text.slice(-4096)))) {
    name = 'Cura'; version = m[1];
  } else if (/^;GENERATOR\.NAME:\s*Cura/im.test(head) || /^;FLAVOR:/m.test(head)) {
    name = 'Cura';
    const v = /^;GENERATOR\.VERSION:\s*(\S+)/im.exec(head);
    version = v ? v[1] : '';
  } else if ((m = /^;\s*(Super ?Slicer|Slic3r|SuperSlicer|Simplify3D|KISSlicer|ideaMaker|IdeaMaker|Creality Print|Snapmaker Luban|Kiri:Moto)[^\n]*?(\d[\w.+-]*)?\s*$/im.exec(head))) {
    name = m[1]; version = m[2] || '';
  }
  const canon = { prusaslicer: 'PrusaSlicer', orcaslicer: 'OrcaSlicer', elegooslicer: 'ElegooSlicer', bambustudio: 'BambuStudio' };
  name = canon[name.toLowerCase().replace(/\s+/g, '')] || name;
  let engine = '';
  const cc = /^;\s*Slicer CC\b\s*v?(\d[\w.+-]*)?/im.exec(head) || (/Slicer CC/i.test(kv.print_settings_id || '') ? [null, ''] : null);
  if (cc) { engine = name; name = 'Slicer CC'; version = cc[1] || ''; }
  return { name, version, engine, date };
}

/** Прямоугольник стола «0x0,256x0,256x256,0x256» -> {x, y} (ширина и глубина). */
function bedFromShape(s) {
  const pts = listOf(s).map((p) => p.split('x').map(Number)).filter((p) => p.length === 2 && p.every(Number.isFinite));
  if (pts.length < 3) return null;
  const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
  const x = Math.max(...xs) - Math.min(...xs), y = Math.max(...ys) - Math.min(...ys);
  return x > 0 && y > 0 ? { x: Math.round(x * 100) / 100, y: Math.round(y * 100) / 100, x0: Math.min(...xs), y0: Math.min(...ys) } : null;
}

/** Первая температура из команд начала: M104/M109 S... (сопло), M140/M190 S... (стол); S0 не считаем. */
function tempsFromCommands(text) {
  const head = text.slice(0, HEAD);
  const out = { nozzle: null, bed: null };
  const re = /^\s*M(104|109|140|190)\b[^;\n]*?\bS(\d+(?:\.\d+)?)/gm;
  let m;
  while ((m = re.exec(head)) && (out.nozzle === null || out.bed === null)) {
    const v = Number(m[2]);
    if (!(v > 0)) continue;
    if ((m[1] === '104' || m[1] === '109') && out.nozzle === null) out.nozzle = v;
    if ((m[1] === '140' || m[1] === '190') && out.bed === null) out.bed = v;
  }
  return out;
}

const BED_TEMP_BY_PLATE = {
  'cool plate': 'cool_plate_temp', 'engineering plate': 'eng_plate_temp', 'high temp plate': 'hot_plate_temp',
  'textured pei plate': 'textured_plate_temp', 'smooth pei plate': 'hot_plate_temp', 'supertack plate': 'supertack_plate_temp',
};

/** Граммы по длине нити: мм * площадь сечения * плотность. */
function gramsFromLength(mm, diameter = DEFAULT_DIAMETER, density = DEFAULT_DENSITY) {
  if (!(mm > 0)) return null;
  const r = (diameter > 0 ? diameter : DEFAULT_DIAMETER) / 2;
  return Math.round(mm * Math.PI * r * r * (density > 0 ? density : DEFAULT_DENSITY) / 1000 * 100) / 100;
}

function color(s) {
  const c = firstOf(s);
  return /^#[0-9a-f]{6}([0-9a-f]{2})?$/i.test(c) ? c.slice(0, 7).toUpperCase() : null;
}

/**
 * @param {string} text G-code (может быть пустым, если сведения только из метаданных)
 * @param {{kv?: object}} extra ключи из метаданных .bgcode или .gcode.3mf - дополняют найденное в тексте
 * @returns {object} сведения; чего нет - null
 */
function parseMeta(text, extra = {}) {
  if (typeof text !== 'string') text = '';
  const kv = Object.assign({}, extra.kv || {}, collectKeys(text));
  const cura = curaSettings(text);
  const slicer = detectSlicer(text, kv);
  if (!slicer.name && extra.producer) {
    const m = /^([A-Za-z][\w ]*?)\s+v?(\d[\w.+-]*)/.exec(extra.producer);
    if (m) { slicer.name = m[1]; slicer.version = m[2]; }
  }
  const get = (...keys) => { for (const k of keys) if (kv[k] !== undefined && kv[k] !== '') return kv[k]; return undefined; };

  // Время: Bambu «total estimated time», Prusa/Orca «estimated printing time (normal mode)», Cura «TIME».
  let timeSec = null;
  const bambuTime = get('model printing time');
  if (bambuTime) { const m = /total estimated time:\s*(.*)$/.exec(bambuTime); timeSec = parseDuration(m ? m[1] : bambuTime); }
  if (timeSec === null) timeSec = parseDuration(get('estimated printing time (normal mode)', 'estimated printing time') || '');
  if (timeSec === null) { const t = numOr(get('TIME', 'PRINT.TIME')); if (t !== null) timeSec = Math.round(t); }
  if (timeSec === null && extra.timeSec !== undefined) timeSec = extra.timeSec;

  const diameter = numOr(firstOf(get('filament_diameter'))) || numOr(cura.material_diameter) || DEFAULT_DIAMETER;
  const density = numOr(firstOf(get('filament_density'))) || null;

  let filamentMm = sumOf(get('filament used [mm]', 'total filament length [mm]'));
  if (filamentMm === null) {
    const cm = get('Filament used');
    if (cm !== undefined) {
      const m = listOf(cm).map((x) => numOr(x)).filter((x) => x !== null);
      if (m.length) filamentMm = Math.round(m.reduce((a, b) => a + b, 0) * 1000 * 100) / 100;
    }
  }
  if (filamentMm === null) {
    const vol = numOr(get('EXTRUDER_TRAIN.0.MATERIAL.VOLUME_USED'));
    if (vol !== null) filamentMm = Math.round(vol / (Math.PI * (diameter / 2) ** 2) * 100) / 100;
  }
  if (filamentMm === null && extra.filamentMm !== undefined) filamentMm = extra.filamentMm;
  let filamentG = numOr(get('total filament used [g]', 'total filament weight [g]'));
  if (filamentG === null) filamentG = sumOf(get('filament used [g]'));
  if (filamentG === null && extra.filamentG !== undefined) filamentG = extra.filamentG;
  const gramsEstimated = filamentG === null && filamentMm !== null;
  if (gramsEstimated) filamentG = gramsFromLength(filamentMm, diameter, density || numOr(cura.material_density) || DEFAULT_DENSITY);
  // Bambu пишет «total filament volume [cm^3]» в мм³ - не берём.
  const filamentCm3 = sumOf(get('filament used [cm3]'));

  const filamentType = firstOf(get('filament_type')) || unquote(cura.material_type || '') || extra.filamentType || null;
  const filamentName = firstOf(get('filament_settings_id')) || null;
  const filamentColor = color(get('filament_colour', 'extruder_colour')) || extra.filamentColor || null;
  const filamentColors = listOf(get('filament_colour')).filter((c) => /^#[0-9a-f]{6}/i.test(c)).map((c) => c.slice(0, 7).toUpperCase());

  const cmd = tempsFromCommands(text);
  let nozzleTemp = numOr(firstOf(get('nozzle_temperature', 'temperature', 'EXTRUDER_TRAIN.0.INITIAL_TEMPERATURE')));
  if (nozzleTemp === null) nozzleTemp = numOr(cura.material_print_temperature) ?? cmd.nozzle;
  let bedTemp = null;
  const plate = String(get('curr_bed_type') || '').toLowerCase().trim();
  if (BED_TEMP_BY_PLATE[plate]) bedTemp = numOr(firstOf(get(BED_TEMP_BY_PLATE[plate])));
  if (bedTemp === null) bedTemp = numOr(firstOf(get('bed_temperature', 'hot_plate_temp', 'BUILD_PLATE.INITIAL_TEMPERATURE')));
  if (bedTemp === null) bedTemp = numOr(cura.material_bed_temperature) ?? cmd.bed;

  const nozzle = numOr(firstOf(get('nozzle_diameter', 'EXTRUDER_TRAIN.0.NOZZLE.DIAMETER'))) ?? numOr(cura.machine_nozzle_size);
  const layerHeight = numOr(get('layer_height', 'Layer height')) ?? numOr(cura.layer_height);
  const layers = numOr(get('total layer number', 'total layers count', 'LAYER_COUNT')) ?? null;
  const printer = firstOf(get('printer_settings_id')) || firstOf(get('printer_model')) || unquote(get('TARGET_MACHINE.NAME') || '') ||
    unquote(cura.machine_name || '') || extra.printer || null;

  let bed = bedFromShape(get('printable_area', 'bed_shape') || '');
  const bedHeight = numOr(get('printable_height', 'max_print_height')) ?? numOr(cura.machine_height);
  if (!bed && numOr(cura.machine_width) && numOr(cura.machine_depth)) bed = { x: numOr(cura.machine_width), y: numOr(cura.machine_depth), x0: 0, y0: 0 };
  if (bed) bed.z = bedHeight || null;

  const settings = Object.assign({}, cura, kv);
  return {
    slicer: slicer.name || null, slicerVersion: slicer.version || null, engine: slicer.engine || null, slicedAt: slicer.date,
    timeSec, filamentMm, filamentG, gramsEstimated, filamentCm3,
    filamentType, filamentName, filamentColor, filamentColors, density, diameter,
    nozzleTemp, bedTemp, nozzle, layerHeight, layers, printer, bed, settings,
  };
}

/** Стоимость по цене катушки: граммы * цена / вес катушки. */
function cost(grams, spoolPrice, spoolGrams = 1000) {
  if (!(grams > 0) || !(spoolPrice >= 0) || !(spoolGrams > 0)) return null;
  return Math.round(grams * spoolPrice / spoolGrams * 100) / 100;
}

/** Влезает ли на стол: габариты выдавленного внутри стола (с допуском 0.5 мм на округления слайсера). */
function fitsBed(bounds, bed, tolerance = 0.5) {
  if (!bounds || !bed || !(bed.x > 0) || !(bed.y > 0)) return null;
  const x0 = bed.x0 || 0, y0 = bed.y0 || 0;
  const inXY = bounds.min[0] >= x0 - tolerance && bounds.min[1] >= y0 - tolerance &&
    bounds.max[0] <= x0 + bed.x + tolerance && bounds.max[1] <= y0 + bed.y + tolerance;
  const inZ = !(bed.z > 0) || bounds.max[2] <= bed.z + tolerance;
  return inXY && inZ;
}

module.exports = { parseMeta, collectKeys, curaSettings, detectSlicer, bedFromShape, tempsFromCommands, gramsFromLength, cost, fitsBed, DEFAULT_DENSITY, DEFAULT_DIAMETER };
